INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (41, '2025-08-10T15:02:05.626621+00:00', 'Unit kerja telah melibatkan secara langsung pimpinan saat penyusunan penetapan kinerja', 14, '(i) Undangan, notula disertai kertas kerja dasar hitung dalam penentuan target kinerja, daftar hadir, dan foto rapat penyusunan penetapan kinerja
(ii) Dokumen PK 2024 yang ditandatangani oleh pimpinan
(iii) Dokumen daftar link PK 2024 yang diupload di PPID
(iv) Seluruh dokumen Matriks Peran Hasil (MPH) dari aplikasi Kipapp yang ditandatangani oleh pimpinan') ON CONFLICT DO NOTHING;
INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (42, '2025-08-10T15:02:05.626621+00:00', 'Pimpinan memantau pencapaian kinerja secara berkala', 14, '(i) Undangan, notula (disertai kendala, solusi, tindak lanjut, PIC tindak lanjut, dan batas waktu tindak lanjut), daftar hadir, foto rapat monitoring capaian kinerja (FRA triwulanan), sesuai pada Simonev') ON CONFLICT DO NOTHING;
INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (43, '2025-08-10T15:02:05.626621+00:00', 'Dokumen perencanaan kinerja sudah ada', 15, '(i) Rencana Strategis (Renstra) 2020–2024 dan Reviu Renstra 2020-2024
(ii) Dokumen PK 2024 yang ditandatangani oleh pimpinan
(iii) Dokumen daftar link Renstra 2020–2024, Reviu Renstra 2020–2024, dan PK 2024 yang diupload di PPID') ON CONFLICT DO NOTHING;
INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (44, '2025-08-10T15:02:05.626621+00:00', 'Perencanaan kinerja telah berorientasi hasil', 15, '(i) Dokumen PK 2024 yang ditandatangani oleh pimpinan
(ii) Dokumen daftar link PK 2024 yang diupload di PPID
(iii) Seluruh dokumen MPH dari aplikasi Kipapp yang ditandatangani oleh pimpinan') ON CONFLICT DO NOTHING;
INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (45, '2025-08-10T15:02:05.626621+00:00', 'Terdapat penetapan Indikator Kinerja Utama (IKU)', 15, '(i) Dokumen Peraturan Kepala BPS Nomor 3 Tahun 2022 terkait Reviu IKU di Lingkungan BPS Tahun 2020-2024
(ii) Surat terkait penyusunan Perjanjian Kinerja 2024') ON CONFLICT DO NOTHING;
INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (46, '2025-08-10T15:02:05.626621+00:00', 'Indikator kinerja telah telah memenuhi kriteria SMART', 15, '(i) Dokumen Laporan Kinerja 2024 yang ditandatangani oleh pimpinan
