INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (47, '2025-08-10T15:02:05.626621+00:00', 'Laporan kinerja telah disusun tepat waktu', 15, '(i) Dokumen Laporan Kinerja 2024 yang ditandatangani oleh pimpinan secara tepat waktu
