INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (48, '2025-08-10T15:02:05.626621+00:00', 'Laporan kinerja telah memberikan informasi tentang kinerja', 15, '(i) Dokumen Laporan Kinerja 2024 yang ditandatangani oleh pimpinan
(ii) Dokumen daftar link Laporan Kinerja 2024 yang diupload di PPID') ON CONFLICT DO NOTHING;
INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (49, '2025-08-10T15:02:05.626621+00:00', 'Terdapat sistem informasi/mekanisme informasi kinerja', 15, '(i) Peraturan Kepala Badan Pusat Statistik Nomor 9 Tahun 2015 tentang Pedoman Penyusunan Sistem Akuntabilitas Kinerja Instansi Pemerintah di Lingkungan Badan Pusat Statistik
(ii) SK Tim SAKIP Tahun 2024
(iii) SOP Pengumpulan Data Kinerja sesuai dengan kondisi masing-masing satuan kerja yang ditandatangani oleh pimpinan (mengacu pada surat Sekretaris Utama terkait Pelaporan Capaian Kinerja Triwulanan Tahun 2024)') ON CONFLICT DO NOTHING;
INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (50, '2025-08-10T15:02:05.626621+00:00', 'Unit kerja telah berupaya meningkatkan kapasitas SDM yang menangani akuntabilitas kinerja', 15, '(i) SK Tim SAKIP Tahun 2024
(ii) Dokumen daftar data individu seluruh anggota Tim SAKIP yang memuat data kompetensi dan sertifikat pembinaan terkait akuntabilitas kinerja (akumulasi kompetensi hingga tahun 2024)') ON CONFLICT DO NOTHING;
INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (51, '2025-08-10T15:02:05.626621+00:00', 'Telah dilakukan public campaign tentang pengendalian gratifikasi', 16, '(i) Dokumentasi atau screenshoot banner/spanduk/media sosial yang menunjukan pengendalian gratifikasi telah dipublikasikan secara berkala (per bulan/triwulan/semester)
(ii) Dokumen sosialisasi larangan gratifikasi dalam rapat internal maupun eksternal (undangan, notulen, daftar hadir)') ON CONFLICT DO NOTHING;
INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (52, '2025-08-10T15:02:05.626621+00:00', 'Pengendalian gratifikasi telah diimplementasikan', 16, '(i) SK terkait unit pengendalian gratifikasi (UPG)
(ii) Mekanisme atau SOP terkait pengendalian gratifikasi
(iii) Laporan implementasi pengendalian gratifikasi') ON CONFLICT DO NOTHING;
INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (53, '2025-08-10T15:02:05.626621+00:00', 'Telah dibangun lingkungan pengendalian', 17, '(i) Dokumen sosialisasi SPIP (undangan, notulen, materi/paparan, daftar hadir, dokumentasi/foto)
(ii) SK tim SPIP
