INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (55, '2025-08-10T15:02:05.626621+00:00', 'Telah dilakukan kegiatan pengendalian untuk meminimalisir risiko yang telah diidentifikasi', 17, '(i) Laporan Manajemen Risiko yang memuat kegiatan pengendalian risiko
