INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (56, '2025-08-10T15:02:05.626621+00:00', 'SPI telah diinformasikan dan dikomunikasikan kepada seluruh pihak terkait', 17, '(i) Dokumentasi pelaksanaan internalisasi/sosialisasi SPI (SPIP, MR, dll) kepada seluruh pegawai (undangan, daftar hadir, notulen, dan naskah paparan)') ON CONFLICT DO NOTHING;
INSERT INTO public."pertanyaan" ("id_pertanyaan", "created_at", "deskripsi_pertanyaan", "id_subpilar", "uraian_buktidukung") VALUES (57, '2025-08-10T15:02:05.626621+00:00', 'Kebijakan Pengaduan masyarakat telah diimplementasikan', 18, '(i) SK petugas Pengelola Pengaduan Masyarakat
(ii) Dokumen kebijakan pengaduan
